mapper.select:
select id, notice_id as noticeId, member_id as memberId, username, nickname, email, send_status as sendStatus, case send_status when 0 then '待发送' when 1 then '成功' when 2 then '失败' else '' end as sendStatusName, fail_reason as failReason, send_time as sendTime from basket_mail_notice_recipient where notice_id = #{noticeId} and send_status = #{sendStatus}
and ( email like concat('%', #{keyword}, '%') or username like concat('%', #{keyword}, '%') or nickname like concat('%', #{keyword}, '%') )
order by id desc
